package com.lianxibu.site.service.jobs;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import com.lianxibu.site.repository.jobs.*;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.datasource.DataSourceTransactionManager;
import org.springframework.transaction.*;
import org.springframework.transaction.support.*;

/** Actual count producer/event/header SQL, with explicitly unavailable source-day ports. */
class EntityHeatSourceOriginTest {
    EntityHeatBusinessProducerTest h;EntityHeatEventProofService events;JdbcEntityHeatOriginHeaders headers;NewsDayReportComponentService days;SourceDayCohortSealService cohorts;FrozenSourceStagePlanService plans;SourceDedupResultProofService fragments;EntityHeatSourceOriginService service;String id;final Instant cutoff=Instant.parse("2026-01-02T21:00:00Z");
    GenerationJdbcStoreTest fixture(){return new GenerationJdbcStoreTest();}
    @BeforeEach void setup(){h=new EntityHeatBusinessProducerTest(){@Override GenerationJdbcStoreTest fixture(){return EntityHeatSourceOriginTest.this.fixture();}};h.setup();h.item("fictional-one","fictional-source","fictional-key");h.business.applyAutomatic(h.command("fictional-one","new",null),h.action("fictional-create","fictional-entity"));id=h.f.jdbc.queryForObject("SELECT id FROM jobs WHERE target_type='entity_decision'",String.class);events=new EntityHeatEventProofService(new JdbcEntityHeatEvents(h.f.source,Set.of("fictional-owner")),new DataSourceTransactionManager(h.f.source));headers=new JdbcEntityHeatOriginHeaders(h.f.source);days=mock(NewsDayReportComponentService.class);cohorts=mock(SourceDayCohortSealService.class);plans=mock(FrozenSourceStagePlanService.class);fragments=mock(SourceDedupResultProofService.class);service=create(EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES);}
    EntityHeatSourceOriginService create(int budget){return new EntityHeatSourceOriginService(headers,events,days,cohorts,plans,fragments,new DataSourceTransactionManager(h.f.source),budget);}
    <T>T rr(java.util.function.Supplier<T> work){var tx=new TransactionTemplate(new DataSourceTransactionManager(h.f.source));tx.setReadOnly(true);tx.setIsolationLevel(TransactionDefinition.ISOLATION_REPEATABLE_READ);return tx.execute(s->work.get());}
    @Test void NativeCountAndHeaderWithoutAnOriginalDayKeepAnExplicitGap(){var value=service.capture(List.of(id),cutoff);assertEquals(Set.of(id),value.requested());assertTrue(value.origins().isEmpty());assertEquals(List.of(new EntityHeatSourceOriginService.Missing(id,"source_day_unproven")),value.missing());assertEquals("fictional-entity",value.headers().get(id).entityId());assertSame(value,rr(()->service.verifyObserved(value)));assertThrows(UnsupportedOperationException.class,()->value.origins().clear());assertThrows(UnsupportedOperationException.class,()->value.headers().clear());assertFalse(value.toString().contains(id));verifyNoInteractions(plans,fragments);}
    @Test void UnknownOriginalEventCannotCreateAnySourceOrInventANativeItem(){var value=service.capture(List.of("b".repeat(64)),cutoff);assertEquals(List.of(new EntityHeatSourceOriginService.Missing("b".repeat(64),"count_event_unknown")),value.missing());assertTrue(value.origins().isEmpty());assertTrue(value.headers().isEmpty());assertSame(value,rr(()->service.verifyObserved(value)));verifyNoInteractions(days,cohorts,plans,fragments);}
    @Test void ChangedNativeEventHeaderOrNewOriginalCohortRejectsTheOldCapture(){var value=service.capture(List.of(id),cutoff);h.f.jdbc.update("UPDATE source_run_items SET revision=revision+1,effective_valid=0 WHERE id='fictional-one'");assertThrows(RuntimeException.class,()->rr(()->service.verifyObserved(value)));var fresh=service.capture(List.of(id),cutoff);assertFalse(fresh.headers().get(id).effectiveValid());h.f.jdbc.update("UPDATE jobs SET reason='Fictional changed original' WHERE id=?",id);assertThrows(RuntimeException.class,()->rr(()->service.verifyObserved(fresh)));setup();var missing=service.capture(List.of(id),cutoff);when(cohorts.readObserved(any())).thenReturn(mock(SourceDayCohortSealService.Sealed.class));assertThrows(RuntimeException.class,()->rr(()->service.verifyObserved(missing)));}
    @Test void CapacityAndInputIdentityCannotBeWeakenedByPartialSelection(){assertThrows(GenerationFlowService.CapacityGuarded.class,()->create(1024).capture(List.of(id),cutoff));assertThrows(RuntimeException.class,()->service.capture(List.of(id,id),cutoff));assertThrows(RuntimeException.class,()->service.capture(List.of("fictional-invalid"),cutoff));assertThrows(RuntimeException.class,()->service.capture(List.of(id),cutoff.plusNanos(1)));assertTrue(service.capture(List.of(),cutoff).origins().isEmpty());}
    @Test void SameIssuerAndExplicitReadonlyRrOwnTheEntireSourceVerification(){var value=service.capture(List.of(id),cutoff);assertThrows(RuntimeException.class,()->service.verifyObserved(value));assertThrows(RuntimeException.class,()->rr(()->create(EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES).verifyObserved(value)));assertThrows(RuntimeException.class,()->rr(()->service.capture(List.of(id),cutoff)));var rc=new TransactionTemplate(new DataSourceTransactionManager(h.f.source));rc.setReadOnly(true);rc.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(RuntimeException.class,()->rc.execute(s->service.verifyObserved(value)));var tx=mock(PlatformTransactionManager.class);var source=mock(javax.sql.DataSource.class);var proof=mock(EntityHeatEventProofService.class);new EntityHeatSourceOriginService(new JdbcEntityHeatOriginHeaders(source),proof,days,cohorts,plans,fragments,tx);verifyNoInteractions(source,proof,tx);assertThrows(NullPointerException.class,()->new EntityHeatSourceOriginService(headers,events,null,cohorts,plans,fragments,tx));}
}
